"use client";

import * as React from "react";
import { type VariantProps } from "class-variance-authority";
import { buttonVariants } from "./kgcraft-button-variants";
import { cn } from "./kgcraft-utils";

export interface ButtonProps
  extends
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, ...props }, ref) => {
    return (
      <button
        className={cn(buttonVariants({ variant, size }), className)}
        ref={ref}
        {...props}
      />
    );
  },
);

Button.displayName = "Button";

import { cva } from "class-variance-authority";

export const buttonVariants = cva(
  "focus-visible:ring-kgcraft-ring hover:-translate-x-0.1 inline-flex cursor-pointer items-center justify-center rounded-md text-sm font-medium transition transition-colors duration-150 text-shadow-sm focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none active:scale-98 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        primary: "bg-kgcraft-primary text-kgcraft-secondary-foreground hover:bg-kgcraft-primary/90",
        secondary:
          "bg-kgcraft-secondary text-kgcraft-secondary-foreground hover:bg-kgcraft-secondary/80",
        outline:
          "border-kgcraft-input bg-kgcraft-background hover:bg-kgcraft-accent hover:text-kgcraft-accent-foreground border",
        briskPrimary:
          "text-kgcraft-secondary-foreground after=[''] bg-kgcraft-primary relative overflow-hidden after:absolute after:-top-5 after:-left-3 after:h-[100px] after:w-[40px] after:-translate-x-20 after:rotate-10 after:bg-neutral-50/22 after:[mask-image:linear-gradient(to_right,transparent,black_40%,black_60%,transparent)] after:backdrop-blur-[0.15px] after:transition-all after:duration-750 hover:after:translate-x-[350%]",
        briskSecondary:
          "border-kgcraft-input text-kgcraft-secondary-foreground after=[''] bg-kgcraft-secondary relative overflow-hidden after:absolute after:-top-5 after:-left-3 after:h-[100px] after:w-[40px] after:-translate-x-20 after:rotate-10 after:bg-neutral-400/22 after:[mask-image:linear-gradient(to_right,transparent,black_40%,black_60%,transparent)] after:transition-all after:duration-1050 hover:after:translate-x-[350%]",
      },
      size: {
        sm: "h-8 rounded-md px-3",
        md: "h-10 px-4 py-2",
        lg: "h-11 px-8",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "md",
    },
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { type VariantProps } from "class-variance-authority";
import { accordianVariants } from "./kgcraft-accordion-variant";
import { cn } from "./kgcraft-utils";
import { ChevronDown, ChevronUp, Minus, Plus } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export interface AccordianProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "content">,
    VariantProps<typeof accordianVariants> {
  iconPosition?: "left" | "right";
  iconType?: "chevron" | "plus-minus";
  content?: React.ReactNode;
}

export const Accordian = React.forwardRef<HTMLDivElement, AccordianProps>(
  (
    {
      className,
      variant,
      iconPosition = "right",
      iconType = "chevron",
      children,
      content,
      ...props
    },
    ref,
  ) => {
    const [isOpen, setIsOpen] = React.useState(false);
    // Helper to render the correct icon based on the type and open state
    const renderIcon = () => {
      if (iconType === "plus-minus") {
        return isOpen ? (
          <Minus className="h-4 w-4 transition-transform duration-200" />
        ) : (
          <Plus className="h-4 w-4 transition-transform duration-200" />
        );
      }
      // Default to chevron
      return isOpen ? (
        <ChevronUp className="h-4 w-4 transition-transform duration-200" />
      ) : (
        <ChevronDown className="h-4 w-4 transition-transform duration-200" />
      );
    };
    return (
      <div className="w-full max-w-xl">
        <div
          className={cn(
            accordianVariants({ variant }),
            // Toggle order of icon and text using CSS flex-row-reverse
            iconPosition === "left" ? "flex-row-reverse justify-end gap-3" : "",
            className,
          )}
          ref={ref}
          onClick={() => setIsOpen(!isOpen)}
          {...props}
        >
          <span>{children || "Accordion Header"}</span>

          <div className="text-kgcraft-muted-foreground shrink-0">{renderIcon()}</div>
        </div>
        {/* AnimatePresence handles animating elements when they mount and unmount */}
        <AnimatePresence initial={false}>
          {isOpen && (
            <motion.div
              initial="collapsed"
              animate="open"
              exit="collapsed"
              variants={{
                open: { opacity: 1, height: "auto" },
                collapsed: { opacity: 0, height: 0 },
              }}
              transition={{ duration: 0.25, ease: "easeInOut" }}
              className="overflow-hidden" // Prevents content from overflowing during height transitions
            >
              <div className="text-kgcraft-muted-foreground pt-2 pb-4 text-sm leading-relaxed">
                {content || "Accordion Content goes here."}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    );
  },
);
Accordian.displayName = "Accordian";

// Keep the original spelling compatible with existing consumers.
export { Accordian as Accordion };
export type AccordionProps = AccordianProps;

import { cva } from "class-variance-authority";

export const accordianVariants = cva(
  "flex cursor-pointer items-center justify-between py-3 font-medium transition-all select-none hover:underline",
  {
    variants: {
      variant: {
        default: "border-kgcraft-border border-b",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
